const fs = require('fs');

const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
if (data.length === 0) process.exit(0);

let ptr = 0;
const L = data[ptr++];
const C = data[ptr++];
const P = data[ptr++];

const black = Array.from({ length: L }, () => Array(C).fill(false));

for (let i = 0; i < P; i++) {
    const x = data[ptr++] - 1;
    const y = data[ptr++] - 1;
    black[x][y] = true;
}

const dirs = [
    [-1, 0],
    [1, 0],
    [0, -1],
    [0, 1]
];

const valid = Array(L * C).fill(false);
const rightId = Array(L * C).fill(-1);

let validCount = 0;
let rightCount = 0;

for (let r = 0; r < L; r++) {
    for (let c = 0; c < C; c++) {
        if (black[r][c]) continue;

        let hasBlackNeighbor = false;

        for (const [dr, dc] of dirs) {
            const nr = r + dr;
            const nc = c + dc;
            if (nr >= 0 && nr < L && nc >= 0 && nc < C && black[nr][nc]) {
                hasBlackNeighbor = true;
                break;
            }
        }

        if (hasBlackNeighbor) {
            const id = r * C + c;
            valid[id] = true;
            validCount++;

            if ((r + c) % 2 === 1) {
                rightId[id] = rightCount++;
            }
        }
    }
}

const leftAdj = [];

for (let r = 0; r < L; r++) {
    for (let c = 0; c < C; c++) {
        const id = r * C + c;

        if (!valid[id] || (r + c) % 2 !== 0) continue;

        const adj = [];

        for (const [dr, dc] of dirs) {
            const nr = r + dr;
            const nc = c + dc;

            if (nr < 0 || nr >= L || nc < 0 || nc >= C) continue;

            const nid = nr * C + nc;

            if (valid[nid] && rightId[nid] !== -1) {
                adj.push(rightId[nid]);
            }
        }

        leftAdj.push(adj);
    }
}

const matchR = Array(rightCount).fill(-1);

function dfs(u, seen) {
    for (const v of leftAdj[u]) {
        if (seen[v]) continue;
        seen[v] = true;

        if (matchR[v] === -1 || dfs(matchR[v], seen)) {
            matchR[v] = u;
            return true;
        }
    }
    return false;
}

let matching = 0;

for (let u = 0; u < leftAdj.length; u++) {
    const seen = Array(rightCount).fill(false);
    if (dfs(u, seen)) {
        matching++;
    }
}

console.log(validCount - matching);
